#pragma once

// The configuration choice: one rule for every place that picks how a model is served when the
// user leaves it to the engine (ninferno-serve without the flags, --plan --no-load, ninferno-ui's
// /api/plan). From facts only (the model's shape, the card's generation, the user's task), no
// measurement on the user's machine:
//
//   memory     the own context each stream holds at a configuration (the plan without the
//              weights: runtime/engine/plan_dry_run.h, through OwnContextFn);
//   speed      the seconds of a typical request at it (decode and prefill, choice_constants.h);
//   accuracy   its KLD against the exact reference (choice_constants.h's measured terms).
//
// A drafter is one more axis: plain decode or one of the drafters the
// model carries and the serving Engine runs, each at the configuration chosen for it (the lab's
// measured pair, its group's, a published profile), its memory in the plan and its gain in the
// decode speed; it changes no output (greedy verification), so no accuracy term.
//
// The choice is made at one quantization (a listing row's weights): its candidates are the KV
// codecs x activation modes x drafters x prefill chunks (an MoE's) the model, the card and the
// user's pins allow; the ring and the recurrent state follow the KV codec and the activations
// (coupled_storages), and their other values are scored beside the chosen one to explain them. A
// candidate fits when each stream holds the asked context of its own. Where the generation's
// constants and the accuracy terms rest on two lab cards (Gates), the largest worth
// -ln(T) - lambda KLD wins, T priced on the generation's reference card (choice_constants.h: what a
// decision may read); else the family's defaults stand. An MoE's chunk is the fastest on the
// reference card where its shares rest on two lab cards (it has no accuracy term). Every candidate
// keeps the estimates on the board itself for a caller to show (explain). Which quantization a
// listing serves is the quant rule's, weighed by the worth of each row's own choice where the
// quantization curve decides (product/plan/plan_quants.cpp, weighs_quantizations).
//
// Pure: no CUDA, no files, no clock.

#include "product/choice/choice_constants.h"

#include "ninferno/types.h"

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace ninferno::product::choice {

// ---- Facts.

struct CardFacts {
    int major = 0, minor = 0;   // compute capability
    int sms = 0;                // multiprocessors
    double clock_hz = 0;        // reference SM clock (the PCI-ID table's)
    double dram_bytes_per_s = 0;
    double l2_bytes = 0;        // the L2 cache (0: unknown)
    bool fp4 = false;           // FP4 tensor cores (NVFP4 weights run W4A4)
};

// One way to decode beside plain decode: a drafter the model carries at the configuration chosen
// for it, and its gain.
struct DrafterOption {
    std::string label;     // the configuration, as --spec-config takes it ("mtp:4", "dflash:7")
    std::string drafter;   // the drafter's name in the artifact or manifest
    double speedup = 1;    // decode of one stream against plain decode's (the tune's choice)
    // From this many streams a round of every stream decodes plainly (the load table's first
    // bound at depth 0); 0: any number speculates.
    std::uint32_t plain_from_streams = 0;
    std::string basis;     // where the gain comes from (measured, preliminary, the registry's)
    // Whether a measurement gives the gain (a profile of this card or a similar one, a lab pair);
    // false for a choice published without its speeds (the "*" profile): its gain is unknown, so
    // the drafter axis is not weighed and the profile's choice stands (never plain decode for a
    // gain of 1 nobody measured).
    bool measured = true;
    // Where the load table bounds the configuration's depth (#303): from `streams` streams on, the
    // gain one request measured at the bounded depth (1 where that depth was not measured: a gain
    // no measurement gives is not counted). A ceiling: the verify of the streams' rows together
    // costs more than one request's, and that is not priced. Ascending by streams; empty: `speedup`
    // wherever it speculates.
    struct LoadGain {
        std::uint32_t streams = 0;
        double speedup        = 1;
        std::uint32_t depth   = 0;    // the depth drafted from `streams` on
        bool bounded          = false; // below the configuration's
        bool measured         = true;
    };
    std::vector<LoadGain> load;

    // The gain at `streams` streams: plain decode's 1 from plain_from_streams on, else the load
    // table's at its last bound below, else `speedup`.
    [[nodiscard]] double speedup_at(std::uint32_t streams) const noexcept {
        if (plain_from_streams != 0 && streams >= plain_from_streams) { return 1; }
        double gain = speedup;
        for (const LoadGain& g : load) {
            if (g.streams > streams) { break; }
            gain = g.speedup;
        }
        return gain;
    }
    // Whether a measurement gives the gain at `streams` streams: `measured`, and the load table's
    // bound in force there measured at its depth (a published profile lists no depths but its
    // choice's). Plain decode's from plain_from_streams on is no gain to measure.
    [[nodiscard]] bool measured_at(std::uint32_t streams) const noexcept {
        if (!measured) { return false; }
        if (plain_from_streams != 0 && streams >= plain_from_streams) { return true; }
        bool known = true;
        for (const LoadGain& g : load) {
            if (g.streams > streams) { break; }
            known = g.measured;
        }
        return known;
    }
};

// A trunk linear by shape (runtime::PlanLinear): N outputs x K inputs, run per_token times a token
// (a routed expert's bank: picks x layers, its grid counting jobs, not tokens).
struct LinearShape {
    double n = 0, k = 0, per_token = 0;
    bool expert = false;
    bool gated  = false; // a gated FFN's gate and up: two matrices of n / 2 rows, one input
    // Its weights' storage format where the file names one (ggml_q4_k, ...; runtime::PlanLinear);
    // "": the quantization's label stands for it.
    std::string format;
};

struct ModelFacts {
    std::string family;               // model_type (qwen3_5_text, gemma4_text, ...)
    double params = 0;                // every weight
    double active_params = 0;         // the layers a token runs and the output head
    int experts = 0, experts_per_token = 0;
    double routed_expert_params = 0;  // all routed experts' weights (0: dense)
    double input_table_params = 0;    // an untied input embedding table (a step reads one row; 0 when tied)
    // Its bytes as stored (a GGUF's token_embd may be another format than the average: Qwen3.5-9B
    // Q4_K_M stores it Q4_K, 4.5 bits against 5.3 on average); 0: unknown, input_table_params at
    // the average bits stands in.
    double input_table_bytes = 0;
    std::uint32_t layers = 0;         // the trunk's layers (a decode step launches kernels per layer)
    double hidden = 0;                // the hidden width (the K of a dense model's linears; 0: unknown)
    // The whole-model calls a prefill runs after the prompt's chunks (the generation prompt's
    // execution boundaries: PlanTargetShape::prompt_tail_calls), each a decode step's reads.
    std::uint32_t prompt_tail_calls = 0;
    // Per-token and per-lane bytes of the state a step reads, by storage
    // (runtime::plan_kv_bytes_per_token, plan_ring_bytes_per_token, plan_state_bytes).
    std::function<std::uint64_t(KvCacheStorage)> kv_bytes_per_token;
    std::function<std::uint64_t(KvCacheStorage)> ring_bytes_per_token; // unset: no sliding layers
    std::function<std::uint64_t(RecurrentStateStorage)> state_bytes;    // unset: no recurrent layers
    std::uint32_t window = 0;         // the sliding window (0: none)
    // A token's attention: heads x (key + value) summed over the full layers (over every earlier
    // token) and the sliding ones (over at most the window); 2 flops each per position.
    double full_attention_width = 0, sliding_attention_width = 0;
    // The full-attention layers and their head width (a key's; 0: unknown): the prompt kernel's grid.
    std::uint32_t full_layers = 0;
    double full_head_dim      = 0;
    double full_kv_heads      = 0; // a full layer's KV heads (0: unknown)
    // The sliding layers likewise (Gemma 4's own attention kernel deals both).
    std::uint32_t sliding_layers = 0;
    double sliding_head_dim      = 0;
    double sliding_kv_heads      = 0;
    // The layers that attend (a KV-shared layer reads an earlier layer's keys: the widths sum over
    // these; 0: the layers above).
    std::uint32_t full_attending_layers = 0, sliding_attending_layers = 0;
    bool recurrent = false;           // Gated DeltaNet layers (a --state-dtype to choose)
    bool fp8_ring  = false;           // its sliding rings take FP8 (Gemma 4, dense decoders)
    std::vector<LinearShape> linears; // the trunk's linears (empty: unknown)
    // The recurrent layers' state of one sequence, elements over every layer (0: none); a prefill's
    // chunked scan runs over it once a token.
    double recurrent_state_elements = 0;
    // The drafters it carries, beside plain decode (Candidate::drafter 0); and the one the server
    // takes where the worth does not decide (its resolved profile's: an index into the candidates'
    // drafters, 0 for plain).
    std::vector<DrafterOption> drafters;
    std::size_t default_drafter = 0;
    [[nodiscard]] bool moe() const noexcept { return experts > 1 && routed_expert_params > 0; }
};

// One quantization of the model (a listing row).
// The GEMM an MoE's routed banks prefill on (runtime::ExpertPrefill, product/plan expert_prefill_of).
enum class ExpertBanks : std::uint8_t { Unknown, Int8, A16, Mxfp4 };

struct QuantOption {
    std::string label;          // as --quant takes it
    // Its files (spec::weights_identity of their SHA-256 digests; "" unknown): a label's measured
    // accuracy point is those files' alone (choice_constants.h kQuantKld).
    std::string files;
    double bits_per_weight = 0;
    double weight_bytes    = 0; // what one decode step reads (product::quant_option_of)
    // Of them, an MoE's routed expert banks as stored (0: unknown, their parameters' share stands in);
    // a step reads the share of them its rows route to.
    double routed_expert_bytes = 0;
    bool supported         = true;
    bool int8_route        = true;  // its linears take int8 activations (every GGUF format: AllowA8)
    bool nvfp4             = false; // NVFP4 weights
    // The routes its weights take (weight_class_of): Q8 prefills on the generic int8 tiles, not
    // ggml's MMQ (a GGUF's Q8_0 converts to q8_g32_fp16, which the int8 tiers take: ops/generic
    // q8_prefill_a8); an Other's decode speed is transferred and it wins no decision on worth
    // (plan_quants).
    WeightClass weights = WeightClass::KQuant;
    // An MoE's prefill apart (DECISIONS 66): its routed banks' GEMM, and the class of its linears
    // outside them (attention, the shared expert); Unknown: the MoE rows price the whole.
    ExpertBanks expert_banks = ExpertBanks::Unknown;
    WeightClass rest_weights = WeightClass::KQuant;
};

// The card's generation as the per-generation tables name it ("ada", "gb20x", ...).
[[nodiscard]] std::string_view generation_of(const CardFacts& card) noexcept;

// The weight class of a quantization: from its weight formats where known (as
// artifact::format_name spells them), else from its label (a hub row: Q4_K / Q5_K / Q6_K mixes;
// Q8, Q8_0 and unsloth's Q8_K_XL, which is Q8_0 with 16-bit tensors). A K-quant mix may carry Q8_0
// and 16-bit tensors; anything else is Other.
[[nodiscard]] WeightClass weight_class_of(const std::vector<std::string>& formats, std::string_view label);

// Whether this card's generation measured the class's decode routes on two cards (kRowsEta).
[[nodiscard]] bool class_measured(const CardFacts& card, WeightClass weights) noexcept;

// The band within which two quantizations' worths are a tie on this card's decisions (the
// generation's measured decode error, kDecodePredictionError; 0 where none is measured).
[[nodiscard]] double worth_band(const CardFacts& card) noexcept;

// What the user asks: the context each stream holds of its own (the contexts in turn: a pinned
// one, or Auto's targets runtime::quant_own_targets gives), the streams, the request shape. The
// request is a mix (DECISIONS 73): the short one (prompt + answer) and a long one whose prompt
// fills the asked context (long_prompt).
struct Task {
    std::vector<std::uint32_t> contexts = {32768};
    std::uint32_t concurrency = 1;
    std::uint32_t prompt      = kRequestPrompt;
    std::uint32_t answer      = kRequestAnswer;
    double accuracy_weight    = kAccuracyWeight;

    // The context the worth is priced at: the largest asked (choose() scores every candidate at
    // it, and again at a step it settles on below it).
    [[nodiscard]] std::uint32_t asked_context() const noexcept {
        std::uint32_t asked = 0;
        for (const std::uint32_t c : contexts) { asked = std::max(asked, c); }
        return asked;
    }

    // The long request's prompt: the asked context less the answer, up to kLongPrompt; 0 where it
    // would not be longer than the short request's (the worth then prices the short one alone).
    [[nodiscard]] std::uint32_t long_prompt() const noexcept {
        const std::uint32_t asked = asked_context();
        const std::uint32_t room  = asked > answer ? asked - answer : 0;
        const std::uint32_t lp    = std::min(room, kLongPrompt);
        return lp > prompt ? lp : 0;
    }
};

// What the user pinned with flags; the choice keeps it.
struct Pins {
    std::optional<KvCacheStorage> kv;
    std::optional<KvCacheStorage> ring;
    std::optional<RecurrentStateStorage> state;
    std::optional<ActivationMode> activations;
    std::optional<std::uint32_t> chunk; // --prefill-chunk
    std::optional<std::size_t> drafter; // --spec given (0: none); a Candidate::drafter
};

// The storages that follow the KV codec and the activations (the owner's rule, 23.10): the sliding
// rings in the KV cache's kind (FP8 under any narrower KV codec where the family's rings take FP8,
// else BF16), the recurrent state one step finer than the KV cache (FP32 under BF16 KV, FP16 under
// a narrower one; FP32 under exact, which refuses a rounded state). Pinned values stay.
struct Coupled {
    KvCacheStorage ring;
    RecurrentStateStorage state;
};
[[nodiscard]] Coupled coupled_storages(const ModelFacts& model, KvCacheStorage kv,
                                       ActivationMode activations, const Pins& pins) noexcept;

struct Candidate {
    KvCacheStorage kv = KvCacheStorage::BFloat16;
    KvCacheStorage ring = KvCacheStorage::BFloat16;
    RecurrentStateStorage state = RecurrentStateStorage::FP32;
    ActivationMode activations = ActivationMode::Fast;
    std::uint32_t chunk = kDefaultChunk; // the widest prefill chunk (the ladder may narrow it)
    std::size_t drafter = 0; // 0: plain decode; i: ModelFacts::drafters[i - 1]
};

// ---- The three estimates.

// The route a candidate's linears take on this card.
[[nodiscard]] Route route_of(const QuantOption& quant, ActivationMode activations,
                             const CardFacts& card) noexcept;

// What a speed estimate rests on (#300). Own: the card's generation's rows, each on two lab cards;
// Transferred: a constant from another generation (kTransferGeneration) or one lab card of this
// one; LentGeneration: the card's compute capability has no row of its own (core/generation.h
// generation_known) and the nearest generation's rates, efficiencies and constants stand in.
enum class SpeedBasis { Own, Transferred, LentGeneration };
[[nodiscard]] constexpr std::string_view speed_basis_name(SpeedBasis basis) noexcept {
    return basis == SpeedBasis::Own ? "own" : basis == SpeedBasis::Transferred ? "transferred" : "lent_generation";
}

struct Speed {
    double decode_per_stream = 0; // tokens a second each stream decodes at the context given
    double prefill           = 0; // prompt tokens a second
    bool transferred         = false; // basis != Own
    SpeedBasis basis         = SpeedBasis::Own;
};

// Decode at `context` tokens in the window with `concurrency` rows, and prefill of a `prompt`
// (0: long enough to fill every chunk), on `card`.
[[nodiscard]] Speed speed_of(const ModelFacts& model, const CardFacts& card,
                             const QuantOption& quant, const Candidate& candidate,
                             std::uint32_t concurrency, double context, std::uint32_t prompt = 0);

